async function fetchRoadRoute(p1, p2) {
  const key = `${p1.join(',')}_${p2.join(',')}`;
  if (OSRM_CACHE[key]) return OSRM_CACHE[key];
  try {
    const url = `https://router.project-osrm.org/route/v1/driving/${p1[1]},${p1[0]};${p2[1]},${p2[0]}?overview=full&geometries=geojson`;
    const res = await fetch(url);
    const data = await res.json();
    if (data.routes && data.routes[0]) {
      const roadCoords = data.routes[0].geometry.coordinates.map(([lng, lat]) => [Number(lat.toFixed(5)), Number(lng.toFixed(5))]);
      const roadDistanceKm = Number((data.routes[0].distance / 1000).toFixed(2));
      const route = { roadCoords, roadDistanceKm };
      OSRM_CACHE[key] = route;
      return route;
    }
  } catch (e) {
    console.warn('OSRM route fetch fallback:', e);
  }
  return null;
}

